   156  otError Ip6::InsertMplOption(Message &aMessage, Header &aIp6Header, MessageInfo &aMessageInfo)
   157  {
   158      otError error = OT_ERROR_NONE;
   159
   160      VerifyOrExit(aIp6Header.GetDestination().IsMulticast() &&
   161                   aIp6Header.GetDestination().GetScope() >= Address::kRealmLocalScope);
   162
   163      if (aIp6Header.GetDestination().IsRealmLocalMulticast())
   164      {
   165          aMessage.RemoveHeader(sizeof(aIp6Header));
   166
   167          if (aIp6Header.GetNextHeader() == kProtoHopOpts)
   168          {
   169              HopByHopHeader hbh;
   170              uint8_t hbhLength = 0;
   171              OptionMpl mplOption;
   172
   173              // read existing hop-by-hop option header
   174              aMessage.Read(0, sizeof(hbh), &hbh);
   175              hbhLength = (hbh.GetLength() + 1) * 8;
   176
   177              VerifyOrExit(hbhLength <= aIp6Header.GetPayloadLength(), error = OT_ERROR_PARSE);
   178
   179              // increase existing hop-by-hop option header length by 8 bytes
   180              hbh.SetLength(hbh.GetLength() + 1);
   181              aMessage.Write(0, sizeof(hbh), &hbh);
   182
   183              // make space for MPL Option + padding by shifting hop-by-hop option header
   184              SuccessOrExit(error = aMessage.Prepend(NULL, 8));
   185              aMessage.CopyTo(8, 0, hbhLength, aMessage);
   186
   187              // insert MPL Option
   188              mMpl.InitOption(mplOption, aIp6Header.GetSource());
   189              aMessage.Write(hbhLength, mplOption.GetTotalLength(), &mplOption);
   190
   191              // insert Pad Option (if needed)
   192              if (mplOption.GetTotalLength() % 8)
   193              {
   194                  OptionPadN padOption;
   195                  padOption.Init(8 - (mplOption.GetTotalLength() % 8));
   196                  aMessage.Write(hbhLength + mplOption.GetTotalLength(), padOption.GetTotalLength(), &padOption);
   197              }
   198
   199              // increase IPv6 Payload Length
   200              aIp6Header.SetPayloadLength(aIp6Header.GetPayloadLength() + 8);
   201          }
   202          else
   203          {
   204              SuccessOrExit(error = AddMplOption(aMessage, aIp6Header));
   205          }
   206
   207          SuccessOrExit(error = aMessage.Prepend(&aIp6Header, sizeof(aIp6Header)));
   208      }
   209      else
   210      {
   211          SuccessOrExit(error = AddTunneledMplOption(aMessage, aIp6Header, aMessageInfo));
   212      }
   213
   214  exit:
   215      return error;
   216  }
